const round2 = (n) => Math.round(n * 100) / 100;
const ZERO_DECIMAL = new Set(["JPY", "KRW", "IDR", "VND", "CLP", "COP", "ARS", "NGN", "PKR", "BDT", "PHP", "HUF"]);
export function decimalsFor(currency) {
  return ZERO_DECIMAL.has(currency) ? 0 : 2;
}
export function formatLocal(amount, market) {
  const d = decimalsFor(market.currency);
  const n = amount.toLocaleString("fr-FR", { minimumFractionDigits: d, maximumFractionDigits: d });
  return `${market.symbol}${n}`;
}
export function formatUsd(amount) {
  return `$${amount.toLocaleString("fr-FR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}
export function convert(usd, market) {
  const raw = usd * market.fxPerUsd;
  return decimalsFor(market.currency) === 0 ? Math.round(raw) : round2(raw);
}
function listPriceFor(edition, market) {
  const base = EDITIONS[edition].usd;
  if (market.regionalListLocal) {
    const ratio = base / EDITIONS.standard.usd;
    const scaled = market.regionalListLocal * ratio;
    return {
      list: decimalsFor(market.currency) === 0 ? Math.round(scaled) : round2(scaled),
      regional: true
    };
  }
  return { list: convert(base, market), regional: false };
}
function bandFor(usdEquivalent, usTotal) {
  const pct = (usdEquivalent - usTotal) / usTotal * 100;
  if (pct <= -30)
    return "cheapest";
  if (pct <= -8)
    return "below-average";
  if (pct < 8)
    return "typical";
  if (pct < 30)
    return "above-average";
  return "most-expensive";
}
function usTotalFor(edition) {
  const us = MARKETS.find((m) => m.code === "US");
  const { list } = listPriceFor(edition, us);
  return round2(list * (1 + us.taxRate));
}
export function priceFor(code, edition = "standard") {
  const market = MARKETS.find((m) => m.code === code) ?? MARKETS[0];
  const { list, regional } = listPriceFor(edition, market);
  const taxLocal = market.taxIncludedInList ? round2(list - list / (1 + market.taxRate)) : round2(list * market.taxRate);
  const totalLocal = market.taxIncludedInList ? list : round2(list + taxLocal);
  const usdEquivalent = round2(totalLocal / market.fxPerUsd);
  const usTotal = usTotalFor(edition);
  return {
    market,
    edition,
    listLocal: list,
    taxLocal,
    totalLocal,
    usdEquivalent,
    vsUsPercent: Math.round((usdEquivalent - usTotal) / usTotal * 1000) / 10,
    regionallyPriced: regional,
    band: bandFor(usdEquivalent, usTotal),
    unconfirmed: !EDITIONS[edition].confirmed
  };
}
export function allPrices(edition = "standard") {
  return MARKETS.map((m) => priceFor(m.code, edition)).sort((a, b) => a.usdEquivalent - b.usdEquivalent);
}
export function importVerdict(code, edition = "standard") {
  const ranked = allPrices(edition);
  const cheapest = ranked[0];
  const home = priceFor(code, edition);
  const savingUsd = round2(home.usdEquivalent - cheapest.usdEquivalent);
  const savingPercent = Math.round(savingUsd / home.usdEquivalent * 1000) / 10;
  const worthIt = savingUsd >= 15 && cheapest.market.code !== home.market.code;
  const headline = cheapest.market.code === home.market.code ? `${home.market.country} est déjà le marché le moins cher de cette liste, il n'y a rien à importer.` : worthIt ? `Acheter en ${cheapest.market.country} coûte environ ${formatUsd(cheapest.usdEquivalent)} contre ${formatUsd(home.usdEquivalent)} chez vous, soit environ ${formatUsd(savingUsd)} (${savingPercent} %) de moins.` : `L'écart entre ${home.market.country} et le marché le moins cher n'est que d'environ ${formatUsd(Math.abs(savingUsd))}, cela ne vaut pas l'effort.`;
  return {
    cheapest,
    home,
    savingUsd,
    savingPercent,
    worthIt,
    headline,
    caveat: "Les prix régionaux des boutiques sont liés à la région de votre compte et, sur la plupart des boutiques, à un moyen de paiement local. Changer de région pour chasser un prix plus bas enfreint généralement les conditions d'utilisation de la boutique et peut vous faire perdre l'accès à votre bibliothèque. Considérez ces chiffres comme une comparaison de prix, pas comme un guide d'achat."
  };
}
export function editionValues(code) {
  const standardUsd = priceFor(code, "standard").usdEquivalent;
  return Object.keys(EDITIONS).map((edition) => {
    const p = priceFor(code, edition);
    const meta = EDITIONS[edition];
    const premium = round2(p.usdEquivalent - standardUsd);
    return {
      edition,
      label: meta.label,
      confirmed: meta.confirmed,
      totalLocal: p.totalLocal,
      usdEquivalent: p.usdEquivalent,
      premiumOverStandardUsd: premium,
      gtaDollars: meta.gtaDollars,
      usdPer100kGta: meta.gtaDollars > 0 ? round2(premium / meta.gtaDollars * 1e5) : null,
      includes: meta.includes
    };
  });
}
export function guessMarketCode(locale) {
  if (!locale)
    return "US";
  const region = locale.split("-")[1]?.toUpperCase();
  return region && MARKETS.some((m) => m.code === region) ? region : "US";
}
export function marketByCode(code) {
  return MARKETS.find((m) => m.code === code);
}
